                html += '<div class="ability-item"><div class="ability-name">体型与外貌</div>';
                html += '<div class="ability-desc">' + escapeHtml(data.appearance) + '</div></div>';
            }
            if(data.adaptation) {
                html += '<div class="ability-item"><div class="ability-name">环境适应</div>';
                html += '<div class="ability-desc">' + escapeHtml(data.adaptation) + '</div></div>';
            }
            html += '</div>';
        }

        // 能力详述
        if(data.abilities.length > 0 || data.habits) {
            html += '<div class="section"><div class="section-title">能力与习性</div>';
            data.abilities.forEach(function(ability) {
                html += '<div class="ability-item"><div class="ability-name">' + escapeHtml(ability.name) + '</div>';
                html += '<div class="ability-desc">' + escapeHtml(ability.desc) + '</div></div>';
            });
            if(data.habits) {
                html += '<div class="ability-item"><div class="ability-name">习性与社会性</div>';
                html += '<div class="ability-desc">' + escapeHtml(data.habits) + '</div></div>';
            }
            html += '</div>';
        }

        // 行为模式
        if(data.encounter || data.attackMode || data.retreat) {
            html += '<div class="section threat-section"><div class="section-title">行为模式</div>';
            if(data.encounter) {
                html += '<div class="behavior-item"><div class="behavior-name">典型遭遇</div>';
                html += '<div class="behavior-desc">' + escapeHtml(data.encounter) + '</div></div>';
            }
            if(data.attackMode) {
                html += '<div class="behavior-item"><div class="behavior-name">攻击模式</div>';
                html += '<div class="behavior-desc">' + escapeHtml(data.attackMode) + '</div></div>';
            }
            if(data.retreat) {
                html += '<div class="behavior-item"><div class="behavior-name">撤退/追击条件</div>';
                html += '<div class="behavior-desc">' + escapeHtml(data.retreat) + '</div></div>';
            }
            html += '</div>';
        }

        // 应对策略
        if(data.recommendedClass || data.envAdvantage || data.weakness) {
            html += '<div class="section"><div class="section-title">应对策略</div>';
